bounded_host_request.command:
set -eu
n=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$n" 2>/dev/null)" = true || exit 81
docker exec -i "$n" node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder,setDefaultAutoSelectFamily} from 'node:dns';
import pg from 'pg';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const e=process.env;
let token;
try{token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim(); if(!token)throw Error();}catch{process.exit(91);}
async function call(method){
 try{
  const r=await fetch('https://api.telegram.org/bot'+token+'/'+method,{signal:AbortSignal.timeout(10000)});
  const d=await r.json();
  if(!r.ok||d.ok!==true)throw Error();
  return d.result;
 }catch{process.exit(92);}
}
const me=await call('getMe');
if(me.is_bot!==true||String(me.username).toLowerCase()!=='createvdobot')process.exit(93);
const hook=await call('getWebhookInfo');
if(hook.url!=='')process.exit(94);
let pool;
try{
 pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:4000});
 const r=await pool.query("SELECT status,price_stars,jsonb_array_length(items) AS items FROM videobot_sticker_products WHERE product_id=$1",['sp_76f23430d1c29ca355960a95']);
 if(r.rowCount!==1||r.rows[0].status!=='published'||Number(r.rows[0].price_stars)!==50||Number(r.rows[0].items)<1)process.exit(95);
} catch{process.exit(96);}finally{await pool?.end().catch(()=>{});}
console.log('BOT_IDENTITY_WEBHOOK_AND_PRODUCT=PASS');
NODE
